from pathlib import Path
import re

def replace_once(text, old, new, label):
    if old not in text: raise SystemExit(f'missing expected text for {label}')
    if text.count(old) != 1: raise SystemExit(f'expected one match for {label}, found {text.count(old)}')
    return text.replace(old, new, 1)

index=Path('index.html'); text=index.read_text(); text=replace_once(text,'.expandable-prompt{max-height:280px}','.expandable-prompt{max-height:80vh}','prompt preview max-height'); index.write_text(text)
